        newNode->frequency = nodes[min1]->frequency + nodes[min2]->frequency;
        int minIdx = min(min1, min2);
        int maxIdx = max(min1, min2);
        nodes[minIdx] = newNode;
        nodes[maxIdx] = nodes[size - 1];
        size--;
    }
    TreeNode<T>* root = nodes[0];
    delete[] nodes;
